export class EventDrivenEmbeddingCache {
  constructor() {
    this.subscribers = new Map();
  }

  subscribe(eventType, callback) {
    if (!this.subscribers.has(eventType)) {
      this.subscribers.set(eventType, []);
    }
    this.subscribers.get(eventType).push(callback);
  }

  publish(eventType, data) {
    if (this.subscribers.has(eventType)) {
      this.subscribers.get(eventType).forEach(callback => callback(data));
    }
  }

  updateEmbedding(agentId, embedding) {
    this.publish('embeddingUpdate', { agentId, embedding });
  }
}

// Example usage
const embeddingCache = new EventDrivenEmbeddingCache();
embeddingCache.subscribe('embeddingUpdate', (data) => {
  console.log(`Embedding updated for agent ${data.agentId}`, data.embedding);
});
embeddingCache.updateEmbedding('agent_1', [0.1, 0.2, 0.3]);